#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"

/* Include the Exo-generated kernel header. */
#include "generated/ludcmp/ludcmp.h"


