from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline LU + forward/back substitution kernel written in Exo.
# The LU factorization is algebraically equivalent to the reference
# PolyBench implementation, but the computation of the U row is
# organized to improve spatial locality along the j dimension.
@proc
def kernel_ludcmp_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # Scalar accumulator reused in the factorization and solves.
    w: DATA_TYPE
    # Index used in backward substitution; kept as a scalar to avoid
    # recomputing n - 1 - ii multiple times.
    i0: size

    # In-place LU decomposition: A is overwritten with L (unit diagonal)
    # in its strictly lower part and U in its upper part.
    for i in seq(0, n):

        # Compute L(i, j) for j < i.
        # This matches the standard Doolittle update:
        #   w = A[i,j] - sum_{k=0}^{j-1} L[i,k] * U[k,j]
        #   L[i,j] = w / U[j,j]
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U(i, j) for j >= i.
        #
        # Reference algorithm (per entry):
        #   for j in seq(i, n):
        #       w = A[i, j]
        #       for k in seq(0, i):
        #           w = w - A[i, k] * A[k, j]
        #       A[i, j] = w
        #
        # Here we instead accumulate directly into A[i, j] and
        # reuse each L[i, k] across the entire row of U:
        #   for k in 0..i-1:
        #     for j in i..n-1:
        #       A[i, j] -= L[i, k] * U[k, j]
        #
        # This is mathematically equivalent, but improves locality:
        # for a fixed k we stream contiguously over j, which is
        # friendlier to caches and vector units.
        for k in seq(0, i):
            for j in seq(i, n):
                A[i, j] = A[i, j] - A[i, k] * A[k, j]

    # Forward substitution: solve L * y = b.
    # L has unit diagonal, stored in the strictly lower part of A.
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # Backward substitution: solve U * x = y.
    #
    # The original C code uses a descending loop:
    #   for (i = n-1; i >= 0; i--) {
    #     w = y[i];
    #     for (j = i+1; j < n; j++)
    #       w -= A[i][j] * x[j];
    #     x[i] = w / A[i][i];
    #   }
    #
    # Exo only supports forward (increasing) loop bounds, so we map
    # a forward loop over ii to i0 = n-1-ii, traversing the rows
    # in reverse order while keeping the inner loop structure intact.
    for ii in seq(0, n):
        i0 = n - 1 - ii
        w = y[i0]
        for j in seq(i0 + 1, n):
            w = w - A[i0, j] * x[j]
        x[i0] = w / A[i0, i0]


