# simplified version of the baseline kernel. This demonstrates the use
# of Exo's scheduling primitives without changing the algorithm.
kernel_ludcmp_scheduled = simplify(kernel_ludcmp_base)
kernel_ludcmp = rename(kernel_ludcmp_scheduled, "kernel_ludcmp")

