    #   for (j = 0; j < i; j++) {
    #     w = A[i][j];
    #     for (k = 0; k < j; k++)
    #       w -= A[i][k] * A[k][j];
    #     A[i][j] = w / A[j][j];
    #   }
    #   for (j = i; j < n; j++) {
    #     w = A[i][j];
    #     for (k = 0; k < i; k++)
