def kernel_ludcmp(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # The PolyBench driver always uses n >= 1, but we document it explicitly.
    assert n >= 1

    # Temporary scalar reused across phases.
    w: DATA_TYPE

    # -------------------------------------------------------------------------
    # 1) LU decomposition of A in-place: A = L * U,
    #    with unit diagonal L (L[i,i] = 1) and U stored in the upper triangle.
    # -------------------------------------------------------------------------
    for i in seq(0, n):

        # ---- L part: compute A[i, j] for j < i (strictly lower-triangular) ----
        # This is the standard Doolittle update:
        #   L[i,j] = ( A[i,j] - sum_{k=0..j-1} L[i,k] * U[k,j] ) / U[j,j]
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # ---- U part: compute A[i, j] for j >= i (upper-triangular) ------------
        #
        # Original PolyBench code (for row i):
        #   for (j = i; j < n; j++) {
        #     w = A[i][j];
        #     for (k = 0; k < i; k++)
        #       w -= A[i][k] * A[k][j];
        #     A[i][j] = w;
        #   }
        #
        # This can be written equivalently as a series of rank-1 updates:
        #
        #   for (k = 0; k < i; k++)
        #     for (j = i; j < n; j++)
        #       A[i][j] -= A[i][k] * A[k][j];
        #
        # which performs:
        #   A[i,j] = A[i,j]_orig - sum_{k=0..i-1} A[i,k] * A[k,j]
        #
        # Using this in-place update improves cache locality:
        #   - A[k, j] is traversed row-wise (contiguous in memory),
        #   - A[i, j] is updated row-wise, also contiguous.
        for k in seq(0, i):
            for j in seq(i, n):
                A[i, j] = A[i, j] - A[i, k] * A[k, j]

    # -------------------------------------------------------------------------
    # 2) Forward substitution: solve L * y = b.
    #    L is the unit-lower-triangular part of A (diagonal is 1).
    # -------------------------------------------------------------------------
