    # 3) Backward substitution: solve U * x = y.
    #
    # Original C (descending in i):
    #
    #   for (i = n-1; i >= 0; i--) {
    #     w = y[i];
    #     for (j = i+1; j < n; j++)
    #       w -= A[i][j] * x[j];
    #     x[i] = w / A[i][i];
    #   }
